nodes.text_raw:
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg: #0f1419;
  --card-bg: #1a1f2e;
  --card-border: #2a3040;
  --text-primary: #e8ecf1;
  --text-secondary: #8b94a6;
  --text-muted: #5c6478;
  --accent: #f0c040;
  --accent-cool: #60a5fa;
  --accent-warm: #f59e0b;
  --divider: #252c3a;
  --hour-bar-bg: #232a3a;
  --hour-bar-fill: #60a5fa;
  --hour-bar-fill-warm: #f59e0b;
  --hour-bar-fill-hot: #ef4444;
  --hour-bar-fill-cold: #67c8ff;
  --font: 'Segoe UI', system-ui, -apple-system, sans-serif;
}

body {
  font-family: var(--font);
  background: #0a0e15;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 48px;
  -webkit-font-smoothing: antialiased;
  background-image:
    radial-gradient(ellipse 80% 60% at 50% -10%, rgba(96,165,250,0.08) 0%, transparent 70%),
    radial-gradient(ellipse 50% 40% at 80% 90%, rgba(240,192,64,0.06) 0%, transparent 60%);
}

.card {
  width: 720px;
  background: var(--card-bg);
  border: 1px solid var(--card-border);
  border-radius: 24px;
  padding: 40px 44px 36px;
  box-shadow:
    0 4px 6px -1px rgba(0,0,0,0.3),
    0 8px 24px -4px rgba(0,0,0,0.4),
    0 24px 64px -12px rgba(0,0,0,0.5);
  position: relative;
  overflow: hidden;
}

.card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  background: linear-gradient(90deg, #60a5fa, #818cf8, #a78bfa);
  border-radius: 24px 24px 0 0;
}

.card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 28px;
}

.location {
  display: flex;
  align-items: center;
  gap: 10px;
}

.location-svg {
  width: 22px;
  height: 22px;
  color: var(--text-secondary);
  flex-shrink: 0;
}

.location-name {
  font-size: 22px;
  font-weight: 600;
  color: var(--text-primary);
  letter-spacing: -0.01em;
  line-height: 1.2;
}

.date-badge {
  font-size: 13px;
  font-weight: 500;
  color: var(--text-secondary);
  background: rgba(96,165,250,0.08);
  border: 1px solid rgba(96,165,250,0.15);
  border-radius: 8px;
  padding: 6px 14px;
  letter-spacing: 0.02em;
  white-space: nowrap;
}

.weather-main {
  display: flex;
  align-items: center;
  gap: 24px;
  margin-bottom: 8px;
}

.weather-icon {
  font-size: 56px;
  line-height: 1;
  filter: drop-shadow(0 2px 8px rgba(255,255,255,0.1));
}

.temps {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.temps-row {
  display: flex;
  align-items: baseline;
  gap: 12px;
}

.temp-max {
  font-size: 48px;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: -0.02em;
  line-height: 1;
}

.temp-min {
  font-size: 20px;
  font-weight: 500;
  color: var(--text-secondary);
  letter-spacing: -0.01em;
}

.temp-label {
  font-size: 14px;
  color: var(--text-muted);
  font-weight: 400;
}

.condition {
  font-size: 16px;
  font-weight: 500;
  color: var(--text-secondary);
  margin-top: 4px;
  letter-spacing: 0.01em;
}

.divider-section {
  margin: 24px 0 20px;
  border: none;
  height: 1px;
  background: var(--divider);
}

.hourly-section-label {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 16px;
}

.hourly-grid {
  display: grid;
  grid-template-columns: repeat(24, 1fr);
  gap: 2px;
  align-items: end;
  height: 140px;
  position: relative;
}

.hour-col {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  justify-content: flex-end;
  height: 100%;
  position: relative;
}

.hour-temp-val {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-secondary);
  white-space: nowrap;
  text-align: center;
}

.hour-bar-wrapper {
  width: 100%;
  display: flex;
  justify-content: center;
  align-items: flex-end;
  flex: 1;
  position: relative;
}

.hour-bar {
  width: 6px;
  min-height: 4px;
  border-radius: 3px 3px 0 0;
  background: var(--hour-bar-fill);
  transition: height 0.4s ease;
  position: relative;
}

.hour-bar.cold { background: var(--hour-bar-fill-cold); }
.hour-bar.cool { background: var(--hour-bar-fill); }
.hour-bar.mild { background: var(--hour-bar-fill-warm); }
.hour-bar.warm { background: var(--hour-bar-fill-warm); }
.hour-bar.hot { background: var(--hour-bar-fill-hot); }

.hour-label {
  font-size: 10px;
  color: var(--text-muted);
  font-weight: 500;
  white-space: nowrap;
  text-align: center;
  margin-top: 2px;
}

.now-indicator {
  position: absolute;
  top: 0;
  bottom: 18px;
  width: 1px;
  background: rgba(240,192,64,0.5);
  z-index: 2;
  pointer-events: none;
}

.now-indicator::after {
  content: 'now';
  position: absolute;
  top: -16px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 9px;
  font-weight: 600;
  color: var(--accent);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  white-space: nowrap;
}

.error-state {
  display: none;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 16px;
  padding: 60px 20px;
  text-align: center;
}

.error-state.active { display: flex; }

.error-icon {
  font-size: 40px;
  opacity: 0.6;
}

.error-title {
  font-size: 17px;
  font-weight: 600;
  color: var(--text-primary);
}

.error-detail {
  font-size: 13px;
  color: var(--text-muted);
  max-width: 320px;
  line-height: 1.5;
}

.loading-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 20px;
  padding: 60px 20px;
}

.spinner {
  width: 36px;
  height: 36px;
  border: 3px solid var(--divider);
  border-top-color: var(--accent-cool);
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}

@keyframes spin { to { transform: rotate(360deg); } }

.card-content.hidden { display: none; }
.loading-state.hidden { display: none; }

.extra-stats {
  display: flex;
  gap: 24px;
  margin-top: 20px;
  padding-top: 18px;
  border-top: 1px solid var(--divider);
}

.stat-item {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.stat-label {
  font-size: 11px;
  font-weight: 500;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.stat-value {
  font-size: 17px;
  font-weight: 600;
  color: var(--text-primary);
  letter-spacing: -0.01em;
}

.stat-range {
  font-size: 12px;
  color: var(--text-secondary);
  font-weight: 400;
}

(function() {
  var WMO = {
    0:  { icon: '&#9728;&#65039;', desc: 'Clear sky' },
    1:  { icon: '&#127780;', desc: 'Mostly clear' },
    2:  { icon: '&#9925;', desc: 'Partly cloudy' },
    3:  { icon: '&#9729;&#65039;', desc: 'Overcast' },
    45: { icon: '&#127787;&#65039;', desc: 'Fog' },
    48: { icon: '&#127787;&#65039;', desc: 'Depositing rime fog' },
    51: { icon: '&#127783;', desc: 'Light drizzle' },
    53: { icon: '&#127783;', desc: 'Moderate drizzle' },
    55: { icon: '&#127783;', desc: 'Dense drizzle' },
    56: { icon: '&#127783;', desc: 'Light freezing drizzle' },
    57: { icon: '&#127783;', desc: 'Dense freezing drizzle' },
    61: { icon: '&#127783;', desc: 'Slight rain' },
    63: { icon: '&#127783;', desc: 'Moderate rain' },
    65: { icon: '&#127783;', desc: 'Heavy rain' },
    66: { icon: '&#127783;', desc: 'Light freezing rain' },
    67: { icon: '&#127783;', desc: 'Heavy freezing rain' },
    71: { icon: '&#10052;&#65039;', desc: 'Slight snow' },
    73: { icon: '&#10052;&#65039;', desc: 'Moderate snow' },
    75: { icon: '&#10052;&#65039;', desc: 'Heavy snow' },
    77: { icon: '&#10052;&#65039;', desc: 'Snow grains' },
    80: { icon: '&#127783;', desc: 'Slight rain showers' },
    81: { icon: '&#127783;', desc: 'Moderate rain showers' },
    82: { icon: '&#127783;', desc: 'Violent rain showers' },
    85: { icon: '&#10052;&#65039;', desc: 'Slight snow showers' },
    86: { icon: '&#10052;&#65039;', desc: 'Heavy snow showers' },
    95: { icon: '&#127785;', desc: 'Thunderstorm' },
    96: { icon: '&#127785;', desc: 'Thunderstorm with slight hail' },
    99: { icon: '&#127785;', desc: 'Thunderstorm with heavy hail' }
  };

  function getWeather(code) {
    return WMO[code] || { icon: '&#9729;&#65039;', desc: 'Unknown' };
  }

  function getTempClass(temp) {
    if (temp >= 30) return 'hot';
    if (temp >= 20) return 'warm';
    if (temp >= 10) return 'mild';
    if (temp >= 0)  return 'cool';
    return 'cold';
  }

  function fmtDate(dateStr) {
    var d = new Date(dateStr + 'T00:00:00Z');
    return d.toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', timeZone: 'UTC' });
  }

  function showError(detail) {
    document.querySelector('.loading-state').classList.add('hidden');
    document.querySelector('.card-content').classList.add('hidden');
    var err = document.getElementById('errorState');
    err.classList.add('active');
    if (detail) document.getElementById('errorDetail').textContent = detail;
  }

  function showContent() {
    document.querySelector('.loading-state').classList.add('hidden');
    document.getElementById('errorState').classList.remove('active');
    document.querySelector('.card-content').classList.remove('hidden');
  }

  function getParams() {
    var p = new URLSearchParams(location.search);
    var now = new Date();
    var today = now.toISOString().slice(0, 10);
    return {
      lat: parseFloat(p.get('lat')) || 52.52,
      lon: parseFloat(p.get('lon')) || 13.405,
      name: p.get('name') || 'Berlin',
      date: p.get('date') || today
    };
  }

  function apiUrl(params) {
    var today = new Date().toISOString().slice(0, 10);
    var isFuture = params.date > today;
    var isToday = params.date === today;
    var base = (isFuture || isToday) ? '/api/om/forecast' : '/api/om/archive';
    var qs = new URLSearchParams({
      latitude: params.lat,
      longitude: params.lon,
      daily: 'temperature_2m_max,temperature_2m_min,weather_code',
      hourly: 'temperature_2m',
      timezone: 'UTC',
      temperature_unit: 'celsius',
      start_date: params.date,
      end_date: params.date
    });
    return base + '?' + qs.toString();
  }

  function render(params, data) {
    document.getElementById('locationName').textContent = params.name;
    document.getElementById('dateBadge').textContent = fmtDate(params.date);

    var daily = data.daily;
    var hourly = data.hourly;

    if (!daily || !daily.time || daily.time.length === 0 ||
        !hourly || !hourly.time || hourly.time.length === 0) {
      showError('No weather data available for this date and location.');
      return;
    }

    var weatherCode = daily.weather_code[0];
    var w = getWeather(weatherCode);
    document.getElementById('weatherIcon').innerHTML = w.icon;
    document.getElementById('tempMax').textContent = Math.round(daily.temperature_2m_max[0]) + '°';
    document.getElementById('tempMin').textContent = Math.round(daily.temperature_2m_min[0]) + '°';
    document.getElementById('condition').textContent = w.desc;

    var allHours = data.hourly.time;
    var allTemps = data.hourly.temperature_2m;
    var datePrefix = params.date + 'T';
    var filtered = [];
    for (var i = 0; i < allHours.length; i++) {
      if (allHours[i].indexOf(datePrefix) === 0) {
        filtered.push({ time: allHours[i], temp: allTemps[i] });
      }
    }

    var grid = document.getElementById('hourlyGrid');
    grid.innerHTML = '';

    if (filtered.length === 0) {
      var empty = document.createElement('div');
      empty.style.cssText = 'grid-column:1/-1;text-align:center;color:var(--text-muted);font-size:13px;padding:40px 0;';
      empty.textContent = 'No hourly data for this date.';
      grid.appendChild(empty);
    } else {
      var useEvery = filtered.length > 24 ? Math.ceil(filtered.length / 24) : 1;
      var display = [];
      for (var j = 0; j < filtered.length; j += useEvery) {
        display.push(filtered[j]);
      }
      display = display.slice(0, 24);

      var temps = display.map(function(d) { return d.temp; });
      var minT = Math.min.apply(null, temps);
      var maxT = Math.max.apply(null, temps);
      var range = maxT - minT || 1;

      grid.style.gridTemplateColumns = 'repeat(' + display.length + ', 1fr)';

      var todayStr = new Date().toISOString().slice(0, 10);
      if (params.date === todayStr) {
        var nowHour = new Date().getUTCHours();
        for (var k = 0; k < display.length; k++) {
          var h = parseInt(display[k].time.slice(11, 13), 10);
          if (h >= nowHour) {
            var pct = ((k) / display.length) * 100;
            var indicator = document.createElement('div');
            indicator.className = 'now-indicator';
            indicator.style.left = pct + '%';
            grid.style.position = 'relative';
            grid.appendChild(indicator);
            break;
          }
        }
      }

      for (var m = 0; m < display.length; m++) {
        var hour = display[m].time.slice(11, 16);
        var temp = display[m].temp;
        var barH = ((temp - minT) / range) * 85 + 15;

        var col = document.createElement('div');
        col.className = 'hour-col';

        var val = document.createElement('div');
        val.className = 'hour-temp-val';
        val.textContent = Math.round(temp) + '°';

        var wrapper = document.createElement('div');
        wrapper.className = 'hour-bar-wrapper';

        var bar = document.createElement('div');
        bar.className = 'hour-bar ' + getTempClass(temp);
        bar.style.height = barH + '%';

        wrapper.appendChild(bar);

        var label = document.createElement('div');
        label.className = 'hour-label';
        label.textContent = hour.replace(':00', '');

        col.appendChild(val);
        col.appendChild(wrapper);
        col.appendChild(label);
        grid.appendChild(col);
      }
    }

    var avgTemp = Math.round(temps.reduce(function(a,b){return a+b;},0) / temps.length);
    var statHtml = '';
    statHtml += '<div class="stat-item"><span class="stat-label">Avg</span><span class="stat-value">' + avgTemp + '°C</span></div>';
    statHtml += '<div class="stat-item"><span class="stat-label">Range</span><span class="stat-value">' + Math.round(minT) + '° – ' + Math.round(maxT) + '°C</span></div>';
    statHtml += '<div class="stat-item"><span class="stat-label">Condition</span><span class="stat-value" style="font-size:14px;">' + w.desc + '</span></div>';
    document.getElementById('extraStats').innerHTML = statHtml;

    showContent();
  }

  var params = getParams();
  var url = apiUrl(params);
  fetch(url)
    .then(function(r) {
      if (!r.ok) throw new Error('HTTP ' + r.status);
      return r.json();
    })
    .then(function(data) {
      if (data.error) throw new Error(data.reason || 'API error');
      render(params, data);
    })
    .catch(function(e) {
      showError(e.message || 'Failed to fetch weather data. Please check your connection and try again.');
    });
})();
